import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.CVt6dz2a.js";const p=JSON.parse('{"title":"EP.31 GPU 的第二张身份证","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.31-second-id.md","filePath":"comics/EP.31-second-id.md","lastUpdated":1793881879000}'),r={name:"comics/EP.31-second-id.md"};function i(c,e,s,l,n,b){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="ep-31-gpu-的第二张身份证" tabindex="-1">EP.31 GPU 的第二张身份证 <a class="header-anchor" href="#ep-31-gpu-的第二张身份证" aria-label="Permalink to &quot;EP.31 GPU 的第二张身份证&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/31-webgpu/basics">31.1 基础入门：WebGPU 是什么与能力探测</a> 延伸阅读：<a href="./../guide/31-webgpu/advanced">31.2 进阶应用：WebGPURenderer 与 WGSL 管线</a> · <a href="./../guide/31-webgpu/practice">31.3 实战案例：可热切换的渲染后端</a> 动手演示：<a href="./../public/demos/webgpu/capability-lab.html">capability-lab 能力探测台</a> · <a href="./../public/demos/webgpu/webgpu-renderer-lab.html">webgpu-renderer-lab 程序化 IBL</a> · <a href="./../public/demos/webgpu/raw-wgsl-lab.html">raw-wgsl-lab 原生 WGSL 三角形</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君听说&quot;WebGPU 要来了&quot;，担心整个项目要推倒重写；像素酱拦下他：先探测设备，再决定要不要动。</td></tr><tr><td>② 揭秘</td><td>码叔把 WebGL 与 WebGPU 的差异画成四组对照：全局状态换成管线对象、隐式绑定换成 bind group、GLSL 换成 WGSL、同步创建换成异步初始化。同一套 Scene 代码，只是换了一套底盘。</td></tr><tr><td>③ 实证</td><td>像素酱打开能力探测台：adapter 信息、关键 limits、features 列表一目了然，结论是&quot;建议 WebGPU&quot;；切到不支持的机器，页面继续用 WebGL2，画面照样能用。</td></tr><tr><td>④ 结案</td><td>码叔写下迁移三原则：新项目试水、旧项目保留回退、自定义 GLSL 单独评估。结论只有一句：了解即可，不纳入考核，迁移成本可控。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-webgpu-不是-更快的-webgl-是另一套接口" tabindex="-1">① WebGPU 不是&quot;更快的 WebGL&quot;，是另一套接口 <a class="header-anchor" href="#_1-webgpu-不是-更快的-webgl-是另一套接口" aria-label="Permalink to &quot;① WebGPU 不是&quot;更快的 WebGL&quot;，是另一套接口&quot;">​</a></h3><p>WebGL 的核心是一台<strong>全局状态机</strong>：<code>useProgram</code>、<code>bindTexture</code>、<code>enable</code> 一个个开关地设，驱动在背后替你推断资源绑定。WebGPU 把这一切显式化：管线是不可变对象、资源要打包成 bind group、初始化是异步的、计算着色器是一等公民。</p><p>这不是&quot;版本升级&quot;，而是<strong>换了一套底盘</strong>。好处是 CPU 侧的驱动开销更低、资源可见性可预测、compute 能直接上车；代价是代码更长、概念更多。所以 Three.js 的 <code>WebGPURenderer</code> 不是可有可无的封装，而是让业务代码继续写 <code>Scene</code>、<code>Mesh</code>、<code>Material</code> 的关键一层。</p><h3 id="_2-能力探测的三段式与降级链" tabindex="-1">② 能力探测的三段式与降级链 <a class="header-anchor" href="#_2-能力探测的三段式与降级链" aria-label="Permalink to &quot;② 能力探测的三段式与降级链&quot;">​</a></h3><p>支持不支持，不看 UA，只看运行时：</p><table tabindex="0"><thead><tr><th>步骤</th><th>检查</th><th>失败时</th></tr></thead><tbody><tr><td>①</td><td><code>navigator.gpu</code> 是否存在</td><td>继续 WebGL2</td></tr><tr><td>②</td><td><code>requestAdapter()</code> 是否返回 adapter</td><td>继续 WebGL2</td></tr><tr><td>③</td><td><code>requestDevice()</code> 是否成功</td><td>继续 WebGL2</td></tr></tbody></table><p>拿到 adapter 后，再看 <code>adapter.info</code>、<code>adapter.limits</code>、<code>adapter.features</code>。<code>limits</code> 决定&quot;能不能跑&quot;，<code>features</code> 决定&quot;能不能开高画质&quot;，<code>info</code> 只用来分维度上报，不要当精确设备指纹。探测要带超时，不能让首屏等 GPU；<strong>先出画面，再升级后端</strong>，才是对用户友好的顺序。</p><h3 id="_3-webgpurenderer-的启动时序与自动回退" tabindex="-1">③ <code>WebGPURenderer</code> 的启动时序与自动回退 <a class="header-anchor" href="#_3-webgpurenderer-的启动时序与自动回退" aria-label="Permalink to &quot;③ `WebGPURenderer` 的启动时序与自动回退&quot;">​</a></h3><p><code>WebGPURenderer</code> 的启动不是 <code>new</code> 完就能画：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>new WebGPURenderer → setSize → await init() → 挂 canvas → setAnimationLoop</span></span></code></pre></div><p><code>await init()</code> 之前不要渲染，因为它要申请 adapter 与 device；<code>init()</code> 可能失败，所以必须捕获 Promise 拒绝并准备回退。Three.js 内置了自动回退：没有 WebGPU 时自动使用 WebGL2 后端。想主动对照，就传 <code>forceWebGL: true</code>——注意它是<strong>构造参数</strong>，运行时改不了，想切换只能销毁重建。</p><p>判断实际后端不要靠猜：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> isWebGPU</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> renderer.backend.isWebGPUBackend</span></span></code></pre></div><p>这个字段应该同时用于 UI 展示与埋点，它是&quot;后端选择的唯一真相&quot;。</p><h3 id="_4-迁移三原则-把风险关在笼子里" tabindex="-1">④ 迁移三原则：把风险关在笼子里 <a class="header-anchor" href="#_4-迁移三原则-把风险关在笼子里" aria-label="Permalink to &quot;④ 迁移三原则：把风险关在笼子里&quot;">​</a></h3><ul><li><strong>新项目试水</strong>：新项目可以直接用 <code>WebGPURenderer</code>，保留 WebGL2 回退；旧项目没有明确收益就先不动。</li><li><strong>旧项目保留回退</strong>：后端选择要收敛到 <code>createRenderer()</code>，不要让 <code>if (navigator.gpu)</code> 散落在业务代码里。</li><li><strong>自定义 GLSL 单独评估</strong>：GLSL 不会自动变成 WGSL，<code>ShaderMaterial</code>、<code>onBeforeCompile</code> 注入、<code>EffectComposer</code> 链都是硬成本，必须单独排期。</li></ul><p>标准材质会被自动转换成 NodeMaterial，业务代码改动很小；真正的大头是自定义着色器与后处理。把这条边界说清楚，&quot;迁移成本可控&quot;才不是一句空话。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：浏览器不支持 WebGPU，页面会白屏吗？</strong> 不会，只要你按&quot;探测 → 回退&quot;的顺序写。<code>WebGPURenderer</code> 本身也会自动回退到 WebGL2；页面层面再补一句提示文案即可。</li><li><strong>Q：WebGPU 一定更快吗？</strong> 不一定。它主要降低 CPU 驱动开销、提供 compute 能力；如果瓶颈在像素填充或带宽，换后端不会有肉眼可见的帧率提升。先 profiler，再谈迁移。</li><li><strong>Q：自定义 GLSL 材质怎么办？</strong> 不能直接复用。按成本从低到高：标准材质 + 参数调节 → NodeMaterial / TSL 重写 → 原生 WGSL 手写。不要指望自动翻译。</li><li><strong>Q：移动端能用吗？</strong> 部分机型可以，但差异很大。统一用运行时探测 + WebGL2 回退，不要按 UA 写死；同时关注发热与耗电。</li><li><strong>Q：<code>forceWebGL</code> 和自动回退有什么区别？</strong> 一个是主动选择，一个是被动兜底。埋点时必须区分，否则回退率会被高估，&quot;用户手动降级&quot;会被误判成&quot;兼容性故障&quot;。</li><li><strong>Q：热切换后画面变黑，先查什么？</strong> 查四件事：旧循环有没有停、后处理与 RenderTarget 有没有重建、<code>ShaderMaterial</code> 有没有被带过去、<code>init()</code> 有没有完成。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>WebGPU 与 WebGL 在状态管理、资源绑定、着色器语言上的核心差异分别是什么？</li><li>写出能力探测的三段式，并说明每一步失败时应该落到哪条后端。</li><li>如果团队决定&quot;部分模块试用 WebGPU&quot;，你会怎样设计回退与埋点，保证每一步都能回滚？</li></ol><details><summary>答案</summary><ol><li>状态管理：WebGL 是全局状态机，逐次设置开关；WebGPU 是不可变管线对象，创建时一次性烘焙状态。资源绑定：WebGL 隐式绑定、驱动自动推断；WebGPU 显式 bind group + 管线布局。着色器语言：WebGL 用 GLSL / ESSL；WebGPU 用 WGSL。此外 WebGPU 原生支持 compute，初始化是异步的。</li><li>① 判断 <code>navigator.gpu</code>，不存在就继续 WebGL2；② <code>requestAdapter()</code>，返回 null 就继续 WebGL2；③ <code>requestDevice()</code>，失败就继续 WebGL2。三步都成功才使用 WebGPU；探测要带超时，不能阻塞首屏。实际后端用 <code>renderer.backend.isWebGPUBackend</code> 确认。</li><li>先做能力探测与埋点、不改渲染路径；把后端收敛到 <code>createRenderer()</code> 返回的统一接口；用功能开关或 URL 参数只对内部用户开放；逐模块迁移，每个模块保留独立回滚；埋点记录 <code>requested</code> 与 <code>actual</code>、失败原因、探测耗时与切换耗时；后处理与自定义着色器单独排期，不跟着基础渲染一起切。</li></ol></details>',27)])])}const h=t(r,[["render",i]]);export{p as __pageData,h as default};
